CAT = "cpabarConsol"; SEG = "CON"
Q = [
("A reporting entity is the primary beneficiary of a variable interest entity when it has the power to direct the activities that most affect the entity's performance and:",
 "Significant losses or benefits", ["A majority of its voting shares", "A seat on its board", "Its debt guaranteed by others"],
 "The primary beneficiary has both power over the most significant activities and the obligation to absorb losses or the right to receive benefits that could be significant to the VIE."),
("One characteristic that makes a legal entity a variable interest entity is that:",
 "Its equity at risk is too small", ["It has more than one equity owner", "It issues preferred stock", "It is located abroad"],
 "An entity is a VIE when its equity at risk is not enough to finance its activities without additional subordinated financial support, among other conditions."),
("A subsidiary earns net income of $900,000. The 25% noncontrolling interest was measured at fair value, and amortization of acquisition-date fair value adjustments is $60,000 a year. Net income attributable to the noncontrolling interest is:",
 "$210,000", ["$225,000", "$240,000", "$255,000"],
 "Income after the fair value amortization is $900,000 - $60,000 = $840,000, and 25% of $840,000 = $210,000. Ignoring the amortization gives $225,000.",
 (900000 - 60000) * 0.25),
("A foreign subsidiary sells, buys and borrows mostly in its local currency, and its cash flows do not affect the parent's cash flows directly. Its functional currency is most likely:",
 "Its local currency", ["The parent's currency", "The U.S. dollar", "The currency of its debt"],
 "ASC 830 indicators such as cash flows, prices, sales market, expenses and financing in the local currency point to the local currency as functional."),
("Under the current rate method of translating a foreign subsidiary's statements, its inventory is translated at the:",
 "Exchange rate at year end", ["Rate when it was bought", "Average rate for the year", "Rate when it is sold"],
 "Translation from the functional to the reporting currency uses the balance sheet date rate for all assets and liabilities. Historical rates for nonmonetary items apply to remeasurement."),
("When a foreign subsidiary's books are remeasured into its functional currency, the remeasurement gain or loss is reported in:",
 "Net income", ["Other comprehensive income", "Retained earnings directly", "Additional paid-in capital"],
 "Remeasurement under the temporal method produces gains and losses in net income. Translation adjustments from functional to reporting currency go to other comprehensive income."),
("A foreign subsidiary's net assets were FC 1,000,000 at the start of the year, and it earned FC 200,000 evenly with no dividends. Rates were $1.10 at the start, $1.15 on average and $1.20 at year end. The translation adjustment for the year is:",
 "$110,000 gain", ["$110,000 loss", "$120,000 gain", "$100,000 gain"],
 "Year-end net assets of FC 1,200,000 x $1.20 = $1,440,000. Beginning net assets at $1.10, $1,100,000, plus income at $1.15, $230,000, total $1,330,000, so the adjustment is a $110,000 gain.",
 1200000 * 1.20 - (1000000 * 1.10 + 200000 * 1.15)),
("Cumulative translation adjustments from translating a foreign subsidiary's statements are reported in:",
 "Accumulated other comprehensive income", ["Retained earnings", "Net income each year as it arises", "Additional paid-in capital"],
 "Translation adjustments flow through other comprehensive income and accumulate in equity until reclassified."),
("Cumulative translation adjustments for a foreign entity are reclassified into net income when the parent:",
 "Sells the foreign entity", ["Pays a dividend from it", "Changes its auditors", "Issues new shares to the public"],
 "The accumulated adjustment is released to earnings on the sale or complete or substantially complete liquidation of the investment in the foreign entity."),
("Under the current rate method, a foreign subsidiary's revenues and expenses are translated at:",
 "Rates when earned or the average", ["The year-end rate", "The historical rate at acquisition", "The parent's budget rate"],
 "Income statement items are translated at the rates on the dates they are recognized, and a weighted-average rate for the period is allowed as a practical approach."),
("A parent sold inventory to its subsidiary at a gross profit of $50,000, and 40% of the goods are still in the subsidiary's inventory at year end. The unrealized profit eliminated in consolidation is:",
 "$20,000", ["$50,000", "$30,000", "$25,000"],
 "Profit is realized only when goods leave the consolidated group, so the 40% still held carries $50,000 x 40% = $20,000 of unrealized profit to eliminate.",
 50000 * 0.40),
("A company holds 30% of the voting equity of a variable interest entity and is its primary beneficiary. The company:",
 "Consolidates the VIE", ["Uses the equity method", "Reports it at fair value", "Discloses it only"],
 "The VIE model looks to power and economics rather than voting control, so the primary beneficiary consolidates whatever its voting share."),
]
